begin;
set local lock_timeout='3s';
do $$
declare actor uuid:=gen_random_uuid(); m public.materia; c public.carrera; p jsonb; old_version timestamptz; token text:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));
begin
 insert into auth.users(id) values(actor);
 insert into public.app_users(id) values(actor);
 insert into public.app_user_roles(user_id,role_code) values(actor,'DIRECTOR_ACADEMICO');
 perform set_config('request.jwt.claim.sub',actor::text,true);
 m:=public.guardar_materia(jsonb_build_object('nombre','DICAPI TEST '||token));
 p:=jsonb_build_object('nombre','DICAPI TEST '||token,'sigla','T'||token,'codigo_curso_dicapi',' mam-009 ','resolucion_malla_curricular','1052-2024 mgp/dicapi','fecha_resolucion_malla','2024-12-27','resolucion_autorizacion_centro','072-26 mgp/dicapi','observaciones_normativas','RD de prueba incorpora materia');
 c:=public.guardar_carrera(p,array[m.id]);
 if c.codigo_curso_dicapi<>'MAM-009' or c.resolucion_malla_curricular<>'1052-2024 MGP/DICAPI' or c.resolucion_autorizacion_centro<>'072-26 MGP/DICAPI' or c.fecha_resolucion_malla<>date '2024-12-27' or c.observaciones_normativas<>'RD de prueba incorpora materia' then raise exception 'Metadata lost or unnormalized'; end if;
 if not exists(select 1 from public.auditoria where registro_id=c.id and new_values->>'codigo_curso_dicapi'='MAM-009') then raise exception 'Metadata not audited'; end if;
 old_version:=c.updated_at;
 p:=jsonb_build_object('id',c.id,'expected_updated_at',c.updated_at::text,'nombre',c.nombre,'sigla',c.sigla);
 c:=public.guardar_carrera(p,array[m.id]);
 if c.codigo_curso_dicapi<>'MAM-009' or c.fecha_resolucion_malla<>date '2024-12-27' then raise exception 'Legacy caller cleared metadata'; end if;
 begin perform public.guardar_carrera(p,array[m.id]); raise exception 'Stale version accepted'; exception when serialization_failure then null; end;
 p:=p||jsonb_build_object('expected_updated_at',c.updated_at::text);
 begin perform public.guardar_carrera(p||jsonb_build_object('codigo_curso_dicapi','INVALID CODE'),array[m.id]); raise exception 'Invalid course code accepted'; exception when check_violation then null; end;
 begin perform public.guardar_carrera(p||jsonb_build_object('observaciones_normativas',repeat('X',2001)),array[m.id]); raise exception 'Oversized notes accepted'; exception when check_violation then null; end;
 begin perform public.guardar_carrera(p||jsonb_build_object('fecha_resolucion_malla','2024-02-30'),array[m.id]); raise exception 'Invalid date accepted'; exception when datetime_field_overflow then null; end;
 begin perform public.guardar_carrera(p||jsonb_build_object('unknown_field','FORGED'),array[m.id]); raise exception 'Unknown field accepted'; exception when invalid_parameter_value then null; end;
 update public.app_user_roles set role_code='COORDINADOR_ACADEMICO' where user_id=actor;
 begin perform public.guardar_carrera(p,array[m.id]); raise exception 'Coordinator edited career'; exception when insufficient_privilege then null; end;
 update public.app_user_roles set role_code='DIRECTOR_ACADEMICO' where user_id=actor;
 c:=public.guardar_carrera(p||jsonb_build_object('codigo_curso_dicapi',null,'resolucion_malla_curricular',null,'fecha_resolucion_malla',null,'resolucion_autorizacion_centro',null,'observaciones_normativas',null),array[m.id]);
 if c.codigo_curso_dicapi is not null or c.fecha_resolucion_malla is not null or c.observaciones_normativas is not null then raise exception 'Cannot clear optional metadata'; end if;
 set constraints all immediate;
end $$;
rollback;
